'use strict';
const KEY='geneva-replica-v1', app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const day=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fresh=()=>({items:GENEVA_VOCAB.map((w,i)=>({...w,id:'w'+i,status:'new'})),daily:[],date:'',queue:[],index:0,outcomes:{}});
let state,storageProblem=false;
try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):fresh();if(!Array.isArray(state.items)||!Array.isArray(state.daily)||!Array.isArray(state.queue))throw Error();}catch{state=fresh();storageProblem=true;}
let filter='all',query='',page=0,reveal=false,preview=[],noticeTimer;
function notify(s){const n=document.querySelector('#notice');n.textContent=s;n.style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.style.display='none',5000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notify('浏览器无法保存进度，请导出备份并检查存储空间。');}}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function ensureDaily(){if(state.date===day())return;const rank={forgotten:0,new:1,remembered:2};state.queue=shuffle([...state.items].sort((a,b)=>rank[a.status]-rank[b.status]).slice(0,50).map(w=>w.id));state.date=day();state.index=0;state.outcomes={};save();}
ensureDaily();
const statusName=s=>({new:'未学',remembered:'已记住',forgotten:'待复习'}[s]||'未学');
const typeName=s=>({word:'单词',phrase:'词组',sentence:'例句'}[s]||'单词');
const word=id=>state.items.find(w=>w.id===id);
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function nav(){const route=location.hash.slice(2).split('/')[0];document.querySelector('#nav').innerHTML=[['','词表'],['daily','每日50'],['curve','曲线'],['import','导入']].map(([path,label])=>`<a class="${route===path?'active':''}" href="#/${path}">${label}</a>`).join('');}
function speechButton(w,example=false){return btn(example?'朗读例句':'♫ 朗读','speak','',`data-id="${esc(w.id)}" data-example="${example}" aria-label="朗读${esc(example?'例句':w.text)}"`);}
function row(w){return `<article class="card word-row"><a href="#/word/${encodeURIComponent(w.id)}"><h2>${esc(w.text)}</h2><p class="muted">${esc(w.translation||'暂无中文释义')}</p></a><span class="badge ${w.status}">${statusName(w.status)}</span>${speechButton(w)}</article>`;}
function list(){const matches=state.items.filter(w=>(filter==='all'||w.status===filter)&&[w.text,w.translation,w.roots].some(v=>String(v||'').toLowerCase().includes(query.toLowerCase())));const pages=Math.max(1,Math.ceil(matches.length/30));page=Math.min(page,pages-1);document.querySelector('#results').innerHTML=`<p class="muted">共 ${matches.length} 条词汇</p><div class="list">${matches.slice(page*30,page*30+30).map(row).join('')||'<p class="empty muted">没有找到匹配的词条</p>'}</div><div class="row page-control">${btn('上一页','prev-page','',page===0?'disabled':'')}<span class="muted">${page+1} / ${pages}</span>${btn('下一页','next-page','',page===pages-1?'disabled':'')}</div>`;}
function home(){const counts={all:state.items.length};for(const s of ['new','remembered','forgotten'])counts[s]=state.items.filter(w=>w.status===s).length;app.innerHTML=`<section class="hero"><p class="eyebrow">Geneva Assault Plan</p><h1>jaja的日内瓦突击计划</h1><p>UNOG / 中国厅 / 瑞士日常 / 酒店导览词库。朗读、释义、例句与记忆曲线，一天推进 50 词。</p><a class="button" href="#/daily">开始今日 50 词</a><div class="stats"><div><strong>${counts.all}</strong><span>词库</span></div><div><strong>${counts.remembered}</strong><span>已记住</span></div><div><strong>${counts.forgotten}</strong><span>待复习</span></div></div></section><div class="search"><input id="search" type="search" placeholder="搜索英文 / 中文 / 词根" aria-label="搜索词库" value="${esc(query)}"></div><div class="filters">${[['all','全部'],['new','未学'],['forgotten','待复习'],['remembered','已记住']].map(([s,n])=>btn(`${n} <span>${counts[s]}</span>`,'filter',filter===s?'active':'',`data-filter="${s}" aria-pressed="${filter===s}"`)).join('')}</div><section id="results" class="space"></section>`;list();document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;page=0;list();});}
function highlighted(text,target){if(!target)return esc(text);const at=text.toLowerCase().indexOf(target.toLowerCase());return at<0?esc(text):`${esc(text.slice(0,at))}<mark>${esc(text.slice(at,at+target.length))}</mark>${esc(text.slice(at+target.length))}`;}
function wordCard(w,detail=false){return `<article class="card drill"><div class="row between"><span class="eyebrow muted">${detail?'Word Details':'Drill Card'}</span>${speechButton(w)}</div><div class="center"><h2 class="term"><a href="#/word/${encodeURIComponent(w.id)}">${esc(w.text)}</a></h2><p class="phonetic">${esc(w.phonetic)}</p></div>${w.example?`<div class="example"><p>${highlighted(w.example,w.text)}</p><details><summary>查看例句翻译</summary><p>${esc(w.exampleZh||'暂无例句翻译')}</p></details><div style="margin-top:14px">${speechButton(w,true)}</div></div>`:''}<div style="margin-top:24px">${!detail?btn(reveal?'隐藏释义':'显示中文释义','reveal','wide soft',`aria-expanded="${reveal}"`):''}${detail||reveal?`<div class="meaning"><p class="answer">${esc(w.translation||'暂无中文释义')}</p><details ${detail?'open':''}><summary>词根词缀 · 拓展解释</summary><p>${esc(w.roots||'暂无词根信息')}</p><p>${esc(w.extension||'暂无拓展解释')}</p></details></div>`:''}</div></article>`;}
function actions(w,daily){return `<div class="actions">${btn('忘记了','mark','no',`data-id="${esc(w.id)}" data-status="forgotten" data-daily="${daily}"`)}${btn('记住了','mark','yes',`data-id="${esc(w.id)}" data-status="remembered" data-daily="${daily}"`)}</div>`;}
function daily(){ensureDaily();if(!state.queue.length){app.innerHTML='<p class="empty">词库为空，请先<a href="#/import">导入单词</a>。</p>';return;}if(state.index>=state.queue.length){const yes=state.queue.map(word).filter(w=>state.outcomes[w.id]==='remembered'),no=state.queue.map(word).filter(w=>state.outcomes[w.id]!=='remembered');app.innerHTML=`<div class="space"><div class="center"><p class="eyebrow muted">Daily · Complete</p><h1>今天也完成了单词学习！</h1><p>恭喜你离去到日内瓦又近了一步！</p><p class="muted">今日 ${state.queue.length} 词 · 记住 ${yes.length} · 还没会／跳过 ${no.length}</p></div><h2 class="remembered">今天已记住</h2>${yes.map(row).join('')||'<p>暂无</p>'}<h2 class="forgotten">今天还没会</h2>${no.map(row).join('')||'<p>暂无</p>'}${btn('复习今天这些词','restart','primary')}<a class="button" href="#/curve">查看学习曲线</a></div>`;return;}const w=word(state.queue[state.index]);app.innerHTML=`<div class="space"><div><h1>每天50词</h1><p class="muted">乱序练习 · 完成后进入今日结算</p></div><div><div class="row between muted"><span>第 ${state.index+1} / ${state.queue.length} 词</span><span>${typeName(w.type)}</span></div><progress value="${state.index+1}" max="${state.queue.length}" aria-label="每日学习进度"></progress></div>${wordCard(w)}${actions(w,true)}<div class="row between">${btn('上一词','prev','',state.index===0?'disabled':'')}${btn('跳过','next')}</div></div>`;}
function detail(id){const w=word(id);if(!w){app.innerHTML='<p class="empty">未找到这个词条。<a href="#/">返回词表</a></p>';return;}app.innerHTML=`<div class="space"><div class="row between"><a class="button" href="#/">返回词表</a><a class="button" href="#/daily">继续每日练习</a></div>${wordCard(w,true)}${actions(w,false)}</div>`;}
function mark(id,status,isDaily){ensureDaily();const w=word(id);if(!w)return;w.status=status;w.updatedAt=new Date().toISOString();let entry=state.daily.find(d=>d.date===day());if(!entry){entry={date:day(),remembered:0,forgotten:0,studied:0};state.daily.push(entry);}entry[status]++;entry.studied++;state.outcomes[id]=status;if(isDaily)state.index++;state.daily=state.daily.slice(-365);save();reveal=false;render();}
function curve(){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return state.daily.find(e=>e.date===day(d))||{date:day(d),remembered:0,forgotten:0,studied:0};});const max=Math.max(5,...days.map(d=>Math.max(d.remembered,d.forgotten)));const point=(v,i)=>`${48+i*94},${220-v/max*180}`;app.innerHTML=`<div class="space"><div><h1>记忆曲线</h1><p class="muted">最近 7 天的学习记录 · 记住与忘记</p></div><div class="card"><svg class="chart" viewBox="0 0 660 270" role="img" aria-label="最近七天记住与忘记次数曲线">${[0,.5,1].map(v=>`<line x1="48" x2="612" y1="${220-v*180}" y2="${220-v*180}"/><text x="8" y="${224-v*180}">${Math.round(v*max)}</text>`).join('')}${['remembered','forgotten'].map((s,j)=>`<polyline fill="none" stroke="${j?'#c45c4a':'#1f7a4c'}" stroke-width="3" points="${days.map((d,i)=>point(d[s],i)).join(' ')}"/>${days.map((d,i)=>`<circle cx="${48+i*94}" cy="${220-d[s]/max*180}" r="4" fill="${j?'#c45c4a':'#1f7a4c'}"><title>${d.date} ${statusName(s)} ${d[s]} 次</title></circle>`).join('')}`).join('')}${days.map((d,i)=>`<text x="${48+i*94}" y="250" text-anchor="middle">${d.date.slice(5).replace('-','/')}</text>`).join('')}</svg><div class="row legend"><span>● 记住了</span><span>● 忘记了</span></div></div><div class="card"><table><thead><tr><th>日期</th><th>学习次数</th><th>记住</th><th>忘记</th></tr></thead><tbody>${days.map(d=>`<tr><td>${d.date.slice(5)}</td><td>${d.studied}</td><td>${d.remembered}</td><td>${d.forgotten}</td></tr>`).join('')}</tbody></table><p class="muted" style="margin-top:16px">曲线统计每次标记操作，重复复习会累计次数。这是学习记录，不是对记忆留存率的预测。</p></div><div class="row">${btn('导出学习备份','backup')}${btn('重置学习进度','reset','danger')}</div></div>`;}
function parseText(text){const items=[];let current=null;const labels={中文:'translation',释义:'translation',词根:'roots',词根词缀:'roots',拓展:'extension',解释:'extension',例句:'example',英文例句:'example',例句翻译:'exampleZh',中文例句:'exampleZh',音标:'phonetic'};for(let line of text.split(/\r?\n/)){line=line.trim().replace(/^\uFEFF/,'');if(!line||/^[#=━─]/.test(line))continue;const label=line.match(/^([^:：]+)[:：]\s*(.*)$/);if(label&&labels[label[1]]&&current){current[labels[label[1]]]=label[2];continue;}line=line.replace(/^\d+[.、)）]\s*/,'').replace(/^[-*•]\s+/,'');let parts=line.split(/\t|\s*\|\s*/).map(s=>s.trim()).filter(Boolean);if(parts.length===1)parts=line.split(/\s+[—–-]\s+|\s*[:：]\s*/);if(parts.length===1){const m=line.match(/^([A-Za-z][^\u4e00-\u9fff]*?)\s*([\u4e00-\u9fff].*)$/);if(m)parts=[m[1].trim(),m[2]];}const en=parts[0]?.trim();if(!en||!/[A-Za-z]/.test(en)||/[\u4e00-\u9fff]/.test(en))continue;current={text:en,type:/[.!?]$/.test(en)||en.split(/\s+/).length>=6?'sentence':/\s|-/.test(en)?'phrase':'word',translation:parts[1]||'',phonetic:'',roots:'',extension:'',example:parts[2]||'',exampleZh:parts[3]||''};items.push(current);}return items;}
function importPage(){app.innerHTML=`<div class="space"><div><h1>导入词表</h1><p class="muted">补充你的英文单词、词组和例句</p></div><section id="drop" class="card upload"><p class="symbol">⇧</p><h2>拖拽 TXT 单词表到此处</h2><p class="muted">在本机解析并预览，确认后加入词库。重复词条自动跳过。</p><div style="margin-top:20px">${btn('选择 TXT 文件','choose','primary')}<input id="file" type="file" accept=".txt,text/plain" hidden></div></section><section class="card space"><h2>或粘贴词表文本</h2><p class="muted">每行一词，字段用竖线或 Tab 分隔：英文 | 中文 | 英文例句 | 中文例句。也支持“英文：中文”。不会自动生成缺失的释义。</p><textarea id="paste" aria-label="粘贴词表" placeholder="Delegate | 代表 | Each delegate must register. | 每位代表须登记。"></textarea><div class="row">${btn('解析并预览','parse','primary')}${btn('下载导入模板','template')}</div><div id="preview"></div></section><section class="card"><h2>学习数据备份</h2><p class="muted">进度保存在当前浏览器。换设备前可导出 JSON 备份，再在新设备恢复。</p><div class="row" style="margin-top:16px">${btn('导出备份','backup')}${btn('恢复 JSON 备份','restore')}<input id="restore-file" type="file" accept=".json,application/json" hidden></div></section></div>`;const file=document.querySelector('#file');file.onchange=()=>loadText(file.files[0]);const drop=document.querySelector('#drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag');};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');loadText(e.dataTransfer.files[0]);};document.querySelector('#restore-file').onchange=restoreFile;}
async function loadText(f){if(!f)return;if(!/\.txt$/i.test(f.name)){notify('请选择 TXT 文件');return;}if(f.size>5*1024*1024){notify('文件过大，请使用 5 MB 以内的 TXT 文件');return;}try{document.querySelector('#paste').value=await f.text();showPreview();}catch{notify('文件读取失败，请重新选择');}}
function showPreview(){preview=parseText(document.querySelector('#paste').value);document.querySelector('#preview').innerHTML=`<div class="row between"><p>识别到 ${preview.length} 条英文词条</p>${preview.length?btn('确认导入词库','confirm-import','primary'):''}</div><div class="preview">${preview.slice(0,100).map(w=>`<p><strong>${esc(w.text)}</strong> ${esc(w.translation)}</p>`).join('')}</div>${preview.length>100?'<p class="muted">仅显示前 100 条预览，确认后将导入全部词条。</p>':''}`;}
function addPreview(){const seen=new Set(state.items.map(w=>w.text.trim().toLowerCase()));let added=0;for(const w of preview){const key=w.text.trim().toLowerCase();if(seen.has(key))continue;seen.add(key);state.items.push({...w,id:crypto.randomUUID(),status:'new'});added++;}const skipped=preview.length-added;save();preview=[];document.querySelector('#preview').innerHTML='';notify(`已补充 ${added} 条到词库，跳过 ${skipped} 条重复词条。新词将参与下一天的每日练习。`);}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function restoreFile(e){const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error();const s=JSON.parse(await f.text());if(!Array.isArray(s.items)||!Array.isArray(s.daily)||!Array.isArray(s.queue)||!s.outcomes||typeof s.outcomes!=='object'||!Number.isInteger(s.index)||s.index<0||s.index>s.queue.length||typeof s.date!=='string')throw Error();const ids=new Set();for(const w of s.items){if(typeof w.id!=='string'||ids.has(w.id)||typeof w.text!=='string'||!['new','remembered','forgotten'].includes(w.status))throw Error();for(const k of ['translation','phonetic','roots','extension','example','exampleZh'])if(w[k]!=null&&typeof w[k]!=='string')throw Error();ids.add(w.id);}if(s.queue.some(id=>!ids.has(id))||s.daily.some(d=>typeof d.date!=='string'||['studied','remembered','forgotten'].some(k=>!Number.isFinite(d[k])||d[k]<0)))throw Error();if(!confirm(`用备份的 ${s.items.length} 条词汇及学习记录替换当前数据？建议先导出当前备份。`))return;state=s;ensureDaily();save();render();notify('备份已恢复');}catch{notify('无法恢复：备份格式不正确或文件过大。现有数据未更改。');}}
function speak(w,example){if(!('speechSynthesis'in window)){notify('当前浏览器不支持朗读，请使用 Chrome 或 Edge。');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(example?w.example:w.text);u.lang='en-GB';u.rate=.85;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-GB')||voices.find(v=>v.lang.startsWith('en'))||null;u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))notify('朗读不可用，请检查设备英语语音包。');};speechSynthesis.speak(u);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='speak'){const w=word(b.dataset.id);if(w)speak(w,b.dataset.example==='true');}else if(a==='filter'){filter=b.dataset.filter;page=0;home();}else if(a==='prev-page'||a==='next-page'){page+=a==='next-page'?1:-1;list();document.querySelector('#results').scrollIntoView({block:'start'});}else if(a==='reveal'){reveal=!reveal;daily();}else if(a==='mark'){mark(b.dataset.id,b.dataset.status,b.dataset.daily==='true');}else if(a==='prev'||a==='next'){state.index=Math.max(0,Math.min(state.queue.length,state.index+(a==='prev'?-1:1)));reveal=false;save();daily();}else if(a==='restart'){state.queue=shuffle(state.queue);state.index=0;state.outcomes={};save();daily();}else if(a==='choose')document.querySelector('#file').click();else if(a==='parse')showPreview();else if(a==='confirm-import')addPreview();else if(a==='template')download('词表导入模板.txt','Delegate | 代表 | Each delegate must register. | 每位代表须登记。\nSecretariat | 秘书处\n','text/plain;charset=utf-8');else if(a==='backup')download(`日内瓦学习备份-${day()}.json`,JSON.stringify(state,null,2),'application/json');else if(a==='restore')document.querySelector('#restore-file').click();else if(a==='reset'&&confirm('清空学习标记和曲线？词库与已导入词条会保留。')){state.items.forEach(w=>w.status='new');state.daily=[];state.date='';ensureDaily();save();render();}});
function render(){nav();const [route,id]=location.hash.slice(2).split('/');if(route==='daily')daily();else if(route==='word')detail(decodeURIComponent(id||''));else if(route==='curve')curve();else if(route==='import')importPage();else home();}
window.addEventListener('hashchange',()=>{reveal=false;if('speechSynthesis'in window)speechSynthesis.cancel();render();window.scrollTo(0,0);});render();if(storageProblem)notify('未能读取本地学习记录，已载入初始词库。');
